script:
"=== testing Zen API connectivity ==="
try {
  $resp = Invoke-WebRequest -Uri "https://opencode.ai/zen/v1/models" -TimeoutSec 15 -UseBasicParsing
  "Status: " + $resp.StatusCode
  $models = ($resp.Content | ConvertFrom-Json).data
  "Total models: " + $models.Count
  "Space bunny found: " + ($models.id -contains "space-bunny-free")
  $models | Where-Object { $_.id -like "*space-bunny*" } | Select-Object id | Select-Object -First 3
} catch {
  "Failed: " + $_.Exception.Message
}
